<?php
declare(strict_types=1);
session_start();
require dirname(__DIR__).'/config/config.php';
require_sign_in();
if(($_SESSION['role']??'')!=='parent'){http_response_code(403);exit('This portal is only available to parent accounts.');}
$db=db();$userId=(int)$_SESSION['user_id'];
$q=$db->prepare("SELECT pg.pupil_id,pg.school_id,pg.relationship,pg.is_primary,p.admission_number,p.first_name,p.middle_name,p.last_name,p.class_level,p.stream,p.status,s.name school_name,COALESCE((SELECT SUM(CASE WHEN l.entry_type IN ('charge','payment_reversal','discount_reversal') THEN l.amount WHEN l.entry_type IN ('payment','charge_reversal','discount') THEN -l.amount ELSE 0 END) FROM school_fee_ledger l WHERE l.school_id=pg.school_id AND l.pupil_id=pg.pupil_id),0) balance FROM pupil_guardians pg JOIN pupils p ON p.id=pg.pupil_id AND p.school_id=pg.school_id JOIN schools s ON s.id=pg.school_id WHERE pg.guardian_user_id=? ORDER BY pg.is_primary DESC,s.name,p.last_name,p.first_name");
$q->execute([$userId]);$children=$q->fetchAll();$attendance=[];$publishedResults=[];$feeEntries=[];$holidayPackages=[];
foreach($children as $child){$id=(int)$child['pupil_id'];$school=(int)$child['school_id'];$q=$db->prepare('SELECT attendance_status,COUNT(*) total FROM pupil_attendance WHERE school_id=? AND pupil_id=? AND attendance_date>=DATE_SUB(CURRENT_DATE,INTERVAL 30 DAY) GROUP BY attendance_status');$q->execute([$school,$id]);$attendance[$id]=$q->fetchAll();$q=$db->prepare("SELECT r.academic_year,r.exam_name,r.assessment,r.subject,r.score,r.max_score,r.updated_at FROM pupil_results r JOIN school_exams x ON x.school_id=r.school_id AND x.name=r.exam_name AND x.academic_year=r.academic_year LEFT JOIN school_classes c ON c.id=x.class_id LEFT JOIN school_class_subjects cs ON cs.id=x.subject_id WHERE r.school_id=? AND r.pupil_id=? AND x.status='results_published' AND (x.class_id IS NULL OR c.name=r.class_level) AND (x.subject_id IS NULL OR cs.name=r.subject) ORDER BY r.academic_year DESC,r.updated_at DESC LIMIT 30");$q->execute([$school,$id]);$publishedResults[$id]=$q->fetchAll();$q=$db->prepare("SELECT entry_type,description,amount,payment_method,reference,created_at FROM school_fee_ledger WHERE school_id=? AND pupil_id=? ORDER BY created_at DESC,id DESC LIMIT 10");$q->execute([$school,$id]);$feeEntries[$id]=$q->fetchAll();$q=$db->prepare("SELECT academic_year,term,published_at FROM pupil_report_cards WHERE school_id=? AND pupil_id=? AND status='published' ORDER BY academic_year DESC,term DESC");$q->execute([$school,$id]);$reportCards[$id]=$q->fetchAll();$q=$db->prepare("SELECT hp.id,hp.title,hp.holiday_period,cs.name subject_name,hp.available_until,COALESCE(pr.status,'assigned') progress_status FROM holiday_packages hp JOIN school_classes c ON c.id=hp.class_id JOIN school_class_subjects cs ON cs.id=hp.subject_id LEFT JOIN holiday_package_progress pr ON pr.package_id=hp.id AND pr.school_id=hp.school_id AND pr.pupil_id=? WHERE hp.school_id=? AND c.name=? AND hp.status='published' AND (hp.available_from IS NULL OR hp.available_from<=CURRENT_DATE) AND (hp.available_until IS NULL OR hp.available_until>=CURRENT_DATE) ORDER BY hp.available_until,hp.title");$q->execute([$id,$school,$child['class_level']]);$holidayPackages[$id]=$q->fetchAll();}
foreach($children as $child){$pid=(int)$child['pupil_id'];$q=$db->prepare("SELECT a.title,a.subject,a.due_date,COALESCE(s.status,'not_started') completion_status FROM homework_assignments a LEFT JOIN pupil_homework_submissions s ON s.assignment_id=a.id AND s.school_id=a.school_id AND s.pupil_id=? WHERE a.school_id=? AND a.class_level=? AND a.status='published' AND (a.due_date IS NULL OR a.due_date>=DATE_SUB(CURRENT_DATE,INTERVAL 30 DAY)) ORDER BY a.due_date IS NULL,a.due_date,a.created_at DESC LIMIT 20");$q->execute([$pid,$child['school_id'],$child['class_level']]);$homework[$pid]=$q->fetchAll();$q=$db->prepare("SELECT subtopic,subject,topic,content,source,note_type FROM learning_notes WHERE status='published' AND class_level=? AND ((note_type='central' AND school_id IS NULL) OR (note_type='teacher' AND school_id=?)) ORDER BY subject,topic,subtopic LIMIT 30");$q->execute([$child['class_level'],$child['school_id']]);$materials[$pid]=$q->fetchAll();}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Parent portal · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Parent portal <span>/</span> My children</div><div class="top-actions"><span class="role-chip">Parent / Guardian</span><div class="user-name"><?=e((string)($_SESSION['name']??'Parent'))?></div></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">FAMILY OVERVIEW</div><h1>Your children</h1><p class="muted">Published school results, recent attendance and fee account summaries for children linked to your account.</p></div></section><?php if(!$children):?><section class="empty-state"><h2>No linked pupils yet</h2><p>Ask your child’s school to verify and link your parent account.</p></section><?php else:?><?php foreach($children as $child):$id=(int)$child['pupil_id'];?><section class="content-section"><div class="section-heading"><div><div class="eyebrow"><?=e($child['school_name'])?><?=!empty($child['is_primary'])?' · Primary guardian':''?></div><h2><?=e(trim($child['first_name'].' '.$child['middle_name'].' '.$child['last_name']))?></h2><p class="muted"><?=e($child['class_level'].($child['stream']?' · '.$child['stream']:'').' · '.$child['admission_number'].' · '.$child['relationship'])?></p></div><span class="count-pill"><?=e(ucfirst($child['status']))?></span></div><div class="metric-grid"><article class="metric-card"><div class="metric-label">FEE BALANCE</div><div class="metric-value">KES <?=e(number_format((float)$child['balance'],2))?></div><div class="metric-note">Net of recorded reversals</div></article><article class="metric-card"><div class="metric-label">ATTENDANCE · LAST 30 DAYS</div><div class="metric-value"><?php $totalAttendance=array_sum(array_map(fn($r)=>(int)$r['total'],$attendance[$id]));?><?=e((string)$totalAttendance)?></div><div class="metric-note">Recorded school days</div></article><article class="metric-card"><div class="metric-label">PUBLISHED ASSESSMENTS</div><div class="metric-value"><?=count($publishedResults[$id])?></div><div class="metric-note">Latest published results</div></article></div><div class="section-heading"><h3>Attendance summary</h3></div><?php if($attendance[$id]):?><p><?php foreach($attendance[$id] as $a):?><span class="count-pill"><?=e(ucfirst($a['attendance_status']).': '.(string)$a['total'])?></span> <?php endforeach;?></p><?php else:?><p class="muted">No attendance has been recorded in the last 30 days.</p><?php endif;?><div class="section-heading"><h3>Published results</h3></div><?php if($publishedResults[$id]):?><div class="table-wrap"><table><thead><tr><th>Year</th><th>Exam</th><th>Subject</th><th>Assessment</th><th>Score</th></tr></thead><tbody><?php foreach($publishedResults[$id] as $result):?><tr><td><?=e((string)$result['academic_year'])?></td><td><?=e($result['exam_name'])?></td><td><?=e($result['subject'])?></td><td><?=e($result['assessment'])?></td><td><?=e(number_format((float)$result['score'],2).' / '.number_format((float)$result['max_score'],2))?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p class="muted">There are no published results to show yet.</p><?php endif;?><?php if(!empty($reportCards[$id])):?><div class="section-heading"><h3>Published report cards</h3></div><div class="question-list"><?php foreach($reportCards[$id] as $card):?><article class="question-card"><h4><?=e($card['academic_year'].' � '.($card['term']?:'Unspecified term'))?></h4><a class="button" href="report_card.php?pupil_id=<?=$id?>&amp;academic_year=<?=$card['academic_year']?>&amp;term=<?=rawurlencode($card['term'])?>">View report card</a></article><?php endforeach;?></div><?php endif;?><div class="section-heading"><h3>Recent fee activity</h3></div><?php if($feeEntries[$id]):?><div class="table-wrap"><table><thead><tr><th>Date</th><th>Entry</th><th>Description</th><th>Amount (KES)</th><th>Method / reference</th></tr></thead><tbody><?php foreach($feeEntries[$id] as $entry):?><tr><td><?=e(date('j M Y',strtotime($entry['created_at'])))?></td><td><?=e(ucwords(str_replace('_',' ',$entry['entry_type'])))?></td><td><?=e($entry['description'])?></td><td><?=e((in_array($entry['entry_type'],['charge','payment_reversal'],true)?'+':'−').' '.number_format((float)$entry['amount'],2))?></td><td><?=e(trim(($entry['payment_method']??'').' '.($entry['reference']??''))?:'—')?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p class="muted">No fee activity has been recorded.</p><?php endif;?></section><section class="content-section"><div class="section-heading"><h3>Holiday learning packages</h3></div><?php if($holidayPackages[$id]):?><div class="question-list"><?php foreach($holidayPackages[$id] as $package):?><article class="question-card"><h4><?=e($package['title'])?></h4><p><?=e($package['subject_name'].' · '.$package['holiday_period'])?></p><p>Progress: <?=e(ucwords(str_replace('_',' ',$package['progress_status'])))?></p><a class="button" href="holiday_package.php?id=<?=$package['id']?>&amp;pupil_id=<?=$id?>">View package</a></article><?php endforeach;?></div><?php else:?><p class="muted">No holiday packages are currently available for this class.</p><?php endif;?></section><section class="content-section"><div class="section-heading"><h3>Learning materials</h3></div><?php if(!empty($materials[$id])):?><div class="question-list"><?php foreach($materials[$id] as $material):?><article class="question-card"><h4><?=e($material['subtopic'])?></h4><p class="muted"><?=e(trim(($material['subject']??'').' · '.($material['topic']??''),' ·'))?></p><div class="learner-material-content"><?=nl2br(e($material['content']))?></div><?php if($material['source']):?><p class="muted">Source: <?=e($material['source'])?></p><?php endif;?></article><?php endforeach;?></div><?php else:?><p class="muted">No published learning materials are available for this class.</p><?php endif;?></section><section class="content-section"><div class="section-heading"><h3>Homework and activities</h3></div><?php if(!empty($homework[$id])):?><div class="question-list"><?php foreach($homework[$id] as $activity):?><article class="question-card"><h4><?=e($activity['title'])?></h4><p><?=e($activity['subject'])?><?php if($activity['due_date']):?> · Due <?=e(date('j M Y',strtotime($activity['due_date'])))?><?php endif;?></p><p class="muted">Status: <?=e(ucwords(str_replace('_',' ',$activity['completion_status'])))?></p></article><?php endforeach;?></div><?php else:?><p class="muted">No homework is currently available for this class.</p><?php endif;?></section><?php endforeach;?><?php endif;?><footer class="page-footer">ShuleLite <span>·</span> Parent portal</footer></div></main></div></body></html>
